import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type ExpenseCategory = 'Travel' | 'Food' | 'Accommodation' | 'Other';

export interface TravelExpense {
  id: string;
  date: string;
  from: string;
  to: string;
  amount: string;
  attachment: File | null;
}

export interface GenericExpense {
  id: string;
  date: string;
  amount: string;
  attachment: File | null;
}

export interface FormData {
  expenseDate: string;
  branchName: string;
  salespersonName: string;
  categories: ExpenseCategory[];
  travelEntries: TravelExpense[];
  foodEntries: GenericExpense[];
  accommodationEntries: GenericExpense[];
  otherEntries: GenericExpense[];
  remark: string;
}

