import React, { useState, useEffect } from 'react';
import { FormCard } from './components/FormCard';
import { BRANCH_SALES_MAPPING, CATEGORIES } from './constants';
import { FormData, ExpenseCategory, TravelExpense, GenericExpense } from './types';
import { submitToGoogleSheets } from './services/googleSheetsService';

const App: React.FC = () => {
  const [formData, setFormData] = useState<FormData>({
    expenseDate: new Date().toISOString().split('T')[0],
    branchName: '',
    salespersonName: '',
    categories: [],
    travelEntries: [],
    foodEntries: [],
    accommodationEntries: [],
    otherEntries: [],
    remark: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  // Sync entries when categories are toggled
  const handleCategoryToggle = (category: ExpenseCategory) => {
    setFormData(prev => {
      const isSelected = prev.categories.includes(category);
      const newCategories = isSelected 
        ? prev.categories.filter(c => c !== category)
        : [...prev.categories, category];

      // Initialize one row if adding
      const updates: Partial<FormData> = { categories: newCategories };
      if (!isSelected) {
        if (category === 'Travel') updates.travelEntries = [{ id: crypto.randomUUID(), date: prev.expenseDate, from: '', to: '', amount: '', attachment: null }];
        if (category === 'Food') updates.foodEntries = [{ id: crypto.randomUUID(), date: prev.expenseDate, amount: '', attachment: null }];
        if (category === 'Accommodation') updates.accommodationEntries = [{ id: crypto.randomUUID(), date: prev.expenseDate, amount: '', attachment: null }];
        if (category === 'Other') updates.otherEntries = [{ id: crypto.randomUUID(), date: prev.expenseDate, amount: '', attachment: null }];
      }

      return { ...prev, ...updates };
    });
  };

  const addRow = (type: 'travel' | 'food' | 'accommodation' | 'other') => {
    setFormData(prev => {
      const common = { id: crypto.randomUUID(), date: prev.expenseDate, amount: '', attachment: null };
      if (type === 'travel') return { ...prev, travelEntries: [...prev.travelEntries, { ...common, from: '', to: '' }] };
      if (type === 'food') return { ...prev, foodEntries: [...prev.foodEntries, common] };
      if (type === 'accommodation') return { ...prev, accommodationEntries: [...prev.accommodationEntries, common] };
      return { ...prev, otherEntries: [...prev.otherEntries, common] };
    });
  };

  const updateEntry = (type: string, id: string, field: string, value: any) => {
    setFormData(prev => {
      const key = `${type}Entries` as keyof FormData;
      const list = prev[key] as any[];
      const newList = list.map(item => item.id === id ? { ...item, [field]: value } : item);
      return { ...prev, [key]: newList };
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.branchName || !formData.salespersonName) {
      alert("Please fill in the Branch and Salesperson name.");
      return;
    }
    setIsSubmitting(true);
    const success = await submitToGoogleSheets(formData);
    setIsSubmitting(false);
    if (success) setIsSuccess(true);
  };

  if (isSuccess) {
    return (
      <div className="max-w-2xl mx-auto py-12 px-4">
        <FormCard isMain>
          <h1 className="text-3xl font-normal mb-4">Expense Report</h1>
          <p className="text-gray-700 mb-6">Your response has been recorded successfully.</p>
          <button 
            onClick={() => window.location.reload()}
            className="text-blue-600 hover:underline text-sm font-medium"
          >
            Submit another response
          </button>
        </FormCard>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto py-8 px-4 sm:px-6">
      {/* Header Card */}
      <FormCard isMain>
        <div className="flex items-center gap-4 mb-4">
          <div className="bg-purple-100 p-2 rounded-full">
            <svg className="w-8 h-8 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
            </svg>
          </div>
          <h1 className="text-3xl font-normal text-gray-900">Company Expense Form</h1>
        </div>
        <div className="border-t border-gray-100 pt-4 mt-2">
          <p className="text-sm text-gray-600">Please fill out all relevant expenses. All fields with * are required.</p>
        </div>
      </FormCard>

      <form onSubmit={handleSubmit} className="space-y-4">
        {/* Core Info */}
        <FormCard>
          <div className="space-y-6">
            <div>
              <label className="block text-base font-medium text-gray-900 mb-2">Expenses Date</label>
              <input 
                type="date" 
                readOnly
                value={formData.expenseDate}
                className="w-full sm:w-1/2 border-b-2 border-gray-200 py-2 focus:border-purple-600 outline-none transition-all"
              />
            </div>

            <div>
              <label className="block text-base font-medium text-gray-900 mb-2">Select Branch Name *</label>
              <select 
                required
                value={formData.branchName}
                onChange={(e) => setFormData({ ...formData, branchName: e.target.value, salespersonName: '' })}
                className="w-full sm:w-1/2 border-b-2 border-gray-200 py-2 focus:border-purple-600 outline-none bg-transparent"
              >
                <option value="">Choose Branch</option>
                {Object.keys(BRANCH_SALES_MAPPING).map(branch => (
                  <option key={branch} value={branch}>{branch}</option>
                ))}
              </select>
            </div>

            {formData.branchName && (
              <div>
                <label className="block text-base font-medium text-gray-900 mb-2">Salesperson Name *</label>
                <select 
                  required
                  value={formData.salespersonName}
                  onChange={(e) => setFormData({ ...formData, salespersonName: e.target.value })}
                  className="w-full sm:w-1/2 border-b-2 border-gray-200 py-2 focus:border-purple-600 outline-none bg-transparent"
                >
                  <option value="">Choose Salesperson</option>
                  {BRANCH_SALES_MAPPING[formData.branchName].map(name => (
                    <option key={name} value={name}>{name}</option>
                  ))}
                </select>
              </div>
            )}
          </div>
        </FormCard>

        {/* Categories Selector */}
        <FormCard>
          <label className="block text-base font-medium text-gray-900 mb-4">Select Expense Categories</label>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
            {CATEGORIES.map(cat => (
              <label key={cat} className="flex items-center space-x-3 cursor-pointer p-2 rounded hover:bg-gray-50">
                <input 
                  type="checkbox" 
                  checked={formData.categories.includes(cat as ExpenseCategory)}
                  onChange={() => handleCategoryToggle(cat as ExpenseCategory)}
                  className="w-5 h-5 text-purple-600 rounded border-gray-300 focus:ring-purple-500"
                />
                <span className="text-gray-700">{cat}</span>
              </label>
            ))}
          </div>
        </FormCard>

        {/* Dynamic Sections */}
        {formData.categories.includes('Travel') && (
          <FormCard>
            <h2 className="text-xl font-medium text-purple-800 mb-4 flex items-center">
              <span className="mr-2">✈️</span> Travel Expenses
            </h2>
            <div className="space-y-8">
              {formData.travelEntries.map((entry, idx) => (
                <div key={entry.id} className="p-4 border border-gray-100 rounded-lg bg-gray-50 relative">
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-xs font-semibold text-gray-500 uppercase">Date</label>
                        <input type="date" value={entry.date} onChange={(e) => updateEntry('travel', entry.id, 'date', e.target.value)} className="w-full bg-transparent border-b border-gray-300 py-1 focus:border-purple-600 outline-none" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-xs font-semibold text-gray-500 uppercase">Amount (₹)</label>
                        <input type="number" placeholder="0.00" value={entry.amount} onChange={(e) => updateEntry('travel', entry.id, 'amount', e.target.value)} className="w-full bg-transparent border-b border-gray-300 py-1 focus:border-purple-600 outline-none" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-xs font-semibold text-gray-500 uppercase">From Location</label>
                        <input type="text" placeholder="Origin" value={entry.from} onChange={(e) => updateEntry('travel', entry.id, 'from', e.target.value)} className="w-full bg-transparent border-b border-gray-300 py-1 focus:border-purple-600 outline-none" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-xs font-semibold text-gray-500 uppercase">To Location</label>
                        <input type="text" placeholder="Destination" value={entry.to} onChange={(e) => updateEntry('travel', entry.id, 'to', e.target.value)} className="w-full bg-transparent border-b border-gray-300 py-1 focus:border-purple-600 outline-none" />
                      </div>
                      <div className="md:col-span-2">
                         <label className="text-xs font-semibold text-gray-500 uppercase block mb-1">Attachment (Image/PDF/Docs)</label>
                         <input type="file" onChange={(e) => updateEntry('travel', entry.id, 'attachment', e.target.files?.[0])} className="text-sm text-gray-600 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-purple-50 file:text-purple-700 hover:file:bg-purple-100" />
                      </div>
                   </div>
                   {idx > 0 && (
                     <button type="button" onClick={() => setFormData(prev => ({ ...prev, travelEntries: prev.travelEntries.filter(e => e.id !== entry.id) }))} className="absolute top-2 right-2 text-red-400 hover:text-red-600">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                     </button>
                   )}
                </div>
              ))}
              <button type="button" onClick={() => addRow('travel')} className="flex items-center text-purple-700 font-medium hover:bg-purple-50 px-4 py-2 rounded-md transition-colors">
                <span className="text-xl mr-2">+</span> Add Travel Row
              </button>
            </div>
          </FormCard>
        )}

        {/* Food Section */}
        {formData.categories.includes('Food') && (
           <FormCard>
            <h2 className="text-xl font-medium text-orange-700 mb-4 flex items-center">
              <span className="mr-2">🍲</span> Food Expenses
            </h2>
