                   </div>
                   <div className="space-y-1">
                      <label className="text-xs font-semibold text-gray-500 uppercase">Amount (₹)</label>
                      <input type="number" placeholder="0.00" value={entry.amount} onChange={(e) => updateEntry('other', entry.id, 'amount', e.target.value)} className="w-full bg-transparent border-b border-gray-300 py-1 focus:border-purple-600 outline-none" />
                   </div>
                   <div className="sm:col-span-2">
                      <label className="text-xs font-semibold text-gray-500 uppercase block mb-1">Attachment</label>
                      <input type="file" onChange={(e) => updateEntry('other', entry.id, 'attachment', e.target.files?.[0])} className="text-sm text-gray-600 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-gray-200 file:text-gray-700 hover:file:bg-gray-300" />
                   </div>
                </div>
              ))}
              <button type="button" onClick={() => addRow('other')} className="flex items-center text-gray-700 font-medium hover:bg-gray-100 px-4 py-2 rounded-md transition-colors">
                <span className="text-xl mr-2">+</span> Add Other Row
              </button>
            </div>
          </FormCard>
        )}

        {/* Remark Card */}
        <FormCard>
           <label className="block text-base font-medium text-gray-900 mb-2">Expenses Description / Purpose / Remark</label>
