            rows={4}
            value={formData.remark}
            onChange={(e) => setFormData({ ...formData, remark: e.target.value })}
            placeholder="Enter additional details here..."
            className="w-full border-b-2 border-gray-200 py-2 focus:border-purple-600 outline-none transition-all resize-none"
           />
        </FormCard>

        {/* Submit Button */}
        <div className="flex justify-between items-center pb-12">
           <button 
            type="submit" 
            disabled={isSubmitting}
            className={`px-8 py-2.5 rounded text-white font-medium text-sm transition-all flex items-center gap-2 ${isSubmitting ? 'bg-gray-400 cursor-not-allowed' : 'bg-purple-700 hover:bg-purple-800 shadow-md'}`}
           >
            {isSubmitting ? (
              <>
                <svg className="animate-spin h-5 w-5 text-white" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                Processing...
              </>
            ) : 'Submit Response'}
           </button>
           <button 
            type="button" 
            onClick={() => window.location.reload()}
            className="text-gray-600 hover:text-gray-800 font-medium text-sm"
           >
            Clear Form
           </button>
        </div>
      </form>

      <p className="text-center text-xs text-gray-500 pb-8">
        This form was created for corporate expense tracking purposes.
      </p>
    </div>
  );
};

export default App;

