import React, { useState, useMemo } from 'react';
import { Plus, Paperclip, X, CheckCircle, Loader2, Sparkles, MapPin, Calendar, CreditCard, Building2 } from 'lucide-react';
import { BRANCHES, SALESPERSONS, GINZA_LOGO_URL } from './constants';
import { BranchName, ExpenseCategory, FormState, ExpenseItem } from './types';
import { GoogleGenAI } from '@google/genai';

const App: React.FC = () => {
  const getToday = () => new Date().toISOString().split('T')[0];

  const createEmptyItem = (): ExpenseItem => ({
    id: Math.random().toString(36).substr(2, 9),
    date: getToday(),
    amount: '',
    fromLocation: '',
    toLocation: '',
    attachment: null
  });

  const [form, setForm] = useState<FormState>({
    date: getToday(),
    branch: '',
    salesperson: '',
    selectedCategories: [],
    expenses: {
      Travel: [createEmptyItem()],
      Food: [createEmptyItem()],
      Accommodation: [createEmptyItem()],
      Other: [createEmptyItem()],
    },
    remark: '',
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [geminiAnalysis, setGeminiAnalysis] = useState<string | null>(null);

  const filteredSalespersons = SALESPERSONS.filter(s => s.branch === form.branch);

  const categorySubtotals = useMemo(() => {
    const subtotals: Record<string, number> = {};
    (Object.keys(form.expenses) as ExpenseCategory[]).forEach(cat => {
      if (form.selectedCategories.includes(cat)) {
        subtotals[cat] = form.expenses[cat].reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0);
      } else {
        subtotals[cat] = 0;
      }
    });
    return subtotals;
  }, [form.expenses, form.selectedCategories]);

  const grandTotal = useMemo(() => {
    return Object.values(categorySubtotals).reduce((sum, val) => sum + val, 0);
  }, [categorySubtotals]);

