import React, { useState, useMemo } from 'react';
import { FormCard } from './components/FormCard';
import { BRANCH_SALES_MAPPING, CATEGORIES } from './constants';
import { FormData, ExpenseCategory } from './types';
import { submitToGoogleSheets } from './services/googleSheetsService';

const App: React.FC = () => {
  const [formData, setFormData] = useState<FormData>({
    expenseDate: new Date().toISOString().split('T')[0],
    branchName: '',
    salespersonName: '',
    categories: [],
    travelEntries: [],
    foodEntries: [],
    accommodationEntries: [],
    otherEntries: [],
    remark: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  // Financial Calculations
  const categorySubtotals = useMemo(() => {
    return {
      Travel: formData.travelEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
      Food: formData.foodEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
      Accommodation: formData.accommodationEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
      Other: formData.otherEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
    };
  }, [formData.travelEntries, formData.foodEntries, formData.accommodationEntries, formData.otherEntries]);

  const grandTotal = useMemo(() => {
    return Object.keys(categorySubtotals).reduce((sum, key) => {
      // Only add to grand total if the category is currently selected
      return formData.categories.includes(key as ExpenseCategory) 
        ? sum + categorySubtotals[key as keyof typeof categorySubtotals] 
        : sum;
    }, 0);
  }, [categorySubtotals, formData.categories]);

  const handleCategoryToggle = (category: ExpenseCategory) => {
    setFormData(prev => {
      const isSelected = prev.categories.includes(category);
      const newCategories = isSelected 
        ? prev.categories.filter(c => c !== category)
        : [...prev.categories, category];

      const updates: Partial<FormData> = { categories: newCategories };
      if (!isSelected) {
        const initialRow = { id: crypto.randomUUID(), date: prev.expenseDate, amount: '', attachment: null };
        if (category === 'Travel') updates.travelEntries = [{ ...initialRow, from: '', to: '' }];
        if (category === 'Food') updates.foodEntries = [initialRow];
        if (category === 'Accommodation') updates.accommodationEntries = [initialRow];
        if (category === 'Other') updates.otherEntries = [initialRow];
      }

      return { ...prev, ...updates };
    });
  };

  const addRow = (type: 'travel' | 'food' | 'accommodation' | 'other') => {
    setFormData(prev => {
      const common = { id: crypto.randomUUID(), date: prev.expenseDate, amount: '', attachment: null };
      if (type === 'travel') return { ...prev, travelEntries: [...prev.travelEntries, { ...common, from: '', to: '' }] };
      if (type === 'food') return { ...prev, foodEntries: [...prev.foodEntries, common] };
      if (type === 'accommodation') return { ...prev, accommodationEntries: [...prev.accommodationEntries, common] };
      return { ...prev, otherEntries: [...prev.otherEntries, common] };
    });
  };

  const updateEntry = (type: string, id: string, field: string, value: any) => {
    setFormData(prev => {
      const key = `${type}Entries` as keyof FormData;
      const list = prev[key] as any[];
      const newList = list.map(item => item.id === id ? { ...item, [field]: value } : item);
      return { ...prev, [key]: newList };
    });
  };

  const removeRow = (type: string, id: string) => {
    setFormData(prev => {
      const key = `${type}Entries` as keyof FormData;
      const list = prev[key] as any[];
      if (list.length <= 1) return prev; // Keep at least one row
      return { ...prev, [key]: list.filter(item => item.id !== id) };
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.branchName || !formData.salespersonName) {
      alert("Please fill in the Branch and Salesperson name.");
      return;
    }
    setIsSubmitting(true);
    const success = await submitToGoogleSheets(formData);
    setIsSubmitting(false);
    if (success) setIsSuccess(true);
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR' }).format(val);
  };

  if (isSuccess) {
    return (
      <div className="max-w-2xl mx-auto py-12 px-4">
        <FormCard isMain>
          <h1 className="text-3xl font-normal mb-4">Expense Report</h1>
          <p className="text-gray-700 mb-6">Your response has been recorded successfully. Grand Total: <strong>{formatCurrency(grandTotal)}</strong></p>
          <button onClick={() => window.location.reload()} className="text-blue-600 hover:underline text-sm font-medium">
            Submit another response
          </button>
        </FormCard>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto py-8 px-4 sm:px-6">
      {/* Header Card */}
      <FormCard isMain>
        <div className="flex items-center gap-5 mb-4">
          <div className="bg-indigo-600 p-3 rounded-xl shadow-md">
             <span className="text-white font-black text-2xl tracking-tighter">GINZA</span>
          </div>
          <div>
            <h1 className="text-3xl font-normal text-gray-900 leading-tight">Corporate Expense Form</h1>
            <p className="text-xs uppercase tracking-widest text-gray-400 font-bold">Ginza Industries Limited</p>
          </div>
        </div>
        <div className="border-t border-gray-100 pt-4 mt-2">
          <p className="text-sm text-gray-600">Enter your official business expenses for reimbursement. All fields marked * are mandatory.</p>
        </div>
      </FormCard>

      <form onSubmit={handleSubmit} className="space-y-4">
        {/* Core Info */}
        <FormCard>
          <div className="space-y-6">
            <div>
              <label className="block text-base font-medium text-gray-900 mb-2">Expenses Date (Fixed to Current)</label>
              <input type="date" readOnly value={formData.expenseDate} className="w-full sm:w-1/2 border-b-2 border-gray-200 py-2 focus:border-purple-600 outline-none bg-gray-50 cursor-default" />
            </div>

            <div>
              <label className="block text-base font-medium text-gray-900 mb-2">Select Branch Name *</label>
              <select required value={formData.branchName} onChange={(e) => setFormData({ ...formData, branchName: e.target.value, salespersonName: '' })} className="w-full sm:w-1/2 border-b-2 border-gray-200 py-2 focus:border-purple-600 outline-none bg-transparent">
                <option value="">Choose Branch</option>
                {Object.keys(BRANCH_SALES_MAPPING).map(branch => <option key={branch} value={branch}>{branch}</option>)}
              </select>
            </div>

            {formData.branchName && (
              <div className="animate-in fade-in duration-300">
                <label className="block text-base font-medium text-gray-900 mb-2">Salesperson Name *</label>
                <select required value={formData.salespersonName} onChange={(e) => setFormData({ ...formData, salespersonName: e.target.value })} className="w-full sm:w-1/2 border-b-2 border-gray-200 py-2 focus:border-purple-600 outline-none bg-transparent">
                  <option value="">Choose Salesperson</option>
                  {BRANCH_SALES_MAPPING[formData.branchName].map(name => <option key={name} value={name}>{name}</option>)}
                </select>
              </div>
            )}
          </div>
        </FormCard>

        {/* Categories Selector */}
        <FormCard>
          <label className="block text-base font-medium text-gray-900 mb-4">Select Expense Categories</label>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
            {CATEGORIES.map(cat => (
              <label key={cat} className={`flex items-center space-x-3 cursor-pointer p-3 rounded-lg border-2 transition-all ${formData.categories.includes(cat as ExpenseCategory) ? 'border-purple-600 bg-purple-50' : 'border-gray-100 hover:bg-gray-50'}`}>
                <input type="checkbox" checked={formData.categories.includes(cat as ExpenseCategory)} onChange={() => handleCategoryToggle(cat as ExpenseCategory)} className="w-5 h-5 text-purple-600 rounded border-gray-300 focus:ring-purple-500" />
                <span className={`text-sm font-medium ${formData.categories.includes(cat as ExpenseCategory) ? 'text-purple-900' : 'text-gray-700'}`}>{cat}</span>
              </label>
            ))}
          </div>
        </FormCard>

        {/* Travel Section */}
        {formData.categories.includes('Travel') && (
          <FormCard>
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-medium text-purple-800 flex items-center">✈️ Travel Expenses</h2>
              <span className="text-sm font-bold text-purple-700 bg-purple-50 px-3 py-1 rounded-full border border-purple-100">Subtotal: {formatCurrency(categorySubtotals.Travel)}</span>
            </div>
            <div className="space-y-6">
              {formData.travelEntries.map((entry, idx) => (
                <div key={entry.id} className="p-4 border border-gray-100 rounded-lg bg-gray-50 relative group">
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">Date</label>
                        <input type="date" value={entry.date} onChange={(e) => updateEntry('travel', entry.id, 'date', e.target.value)} className="w-full bg-transparent border-b border-gray-300 py-1 focus:border-purple-600 outline-none text-sm" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">Amount (₹)</label>
                        <input type="number" placeholder="0.00" value={entry.amount} onChange={(e) => updateEntry('travel', entry.id, 'amount', e.target.value)} className="w-full bg-transparent border-b border-gray-300 py-1 focus:border-purple-600 outline-none text-sm font-bold" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">From Location</label>
                        <input type="text" placeholder="Starting City" value={entry.from} onChange={(e) => updateEntry('travel', entry.id, 'from', e.target.value)} className="w-full bg-transparent border-b border-gray-300 py-1 focus:border-purple-600 outline-none text-sm" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">To Location</label>
                        <input type="text" placeholder="Destination City" value={entry.to} onChange={(e) => updateEntry('travel', entry.id, 'to', e.target.value)} className="w-full bg-transparent border-b border-gray-300 py-1 focus:border-purple-600 outline-none text-sm" />
                      </div>
                      <div className="md:col-span-2">
                        <input type="file" onChange={(e) => updateEntry('travel', entry.id, 'attachment', e.target.files?.[0])} className="text-[10px] text-gray-500 file:mr-2 file:py-1 file:px-3 file:rounded-full file:border-0 file:text-[10px] file:font-semibold file:bg-purple-50 file:text-purple-700 hover:file:bg-purple-100" />
                      </div>
                   </div>
                   {formData.travelEntries.length > 1 && (
                     <button type="button" onClick={() => removeRow('travel', entry.id)} className="absolute top-2 right-2 text-gray-300 hover:text-red-500 transition-colors">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
