        )}

        {/* Accommodation Section */}
        {formData.categories.includes('Accommodation') && (
           <FormCard>
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-medium text-blue-700 flex items-center">🏨 Accommodation Expenses</h2>
              <span className="text-sm font-bold text-blue-700 bg-blue-50 px-3 py-1 rounded-full border border-blue-100">Subtotal: {formatCurrency(categorySubtotals.Accommodation)}</span>
