                      <label className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">Date</label>
                      <input type="date" value={entry.date} onChange={(e) => updateEntry('accommodation', entry.id, 'date', e.target.value)} className="w-full bg-transparent border-b border-gray-300 py-1 focus:border-purple-600 outline-none text-sm" />
