                   <div className="sm:col-span-2">
                      <input type="file" onChange={(e) => updateEntry('accommodation', entry.id, 'attachment', e.target.files?.[0])} className="text-[10px] text-gray-500 file:mr-2 file:py-1 file:px-3 file:rounded-full file:border-0 file:text-[10px] file:font-semibold file:bg-blue-50 file:text-blue-700" />
                   </div>
                   {formData.accommodationEntries.length > 1 && (
                     <button type="button" onClick={() => removeRow('accommodation', entry.id)} className="absolute top-2 right-2 text-gray-300 hover:text-red-500">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                     </button>
                   )}
                </div>
              ))}
              <button type="button" onClick={() => addRow('accommodation')} className="w-full py-2 border-2 border-dashed border-gray-200 rounded-lg text-gray-400 hover:text-blue-600 hover:border-blue-200 hover:bg-blue-50 transition-all text-sm font-medium">+ Add Accomm. Detail</button>
            </div>
          </FormCard>
        )}

        {/* Other Section */}
        {formData.categories.includes('Other') && (
           <FormCard>
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-medium text-gray-700 flex items-center">📁 Other Expenses</h2>
              <span className="text-sm font-bold text-gray-700 bg-gray-50 px-3 py-1 rounded-full border border-gray-200">Subtotal: {formatCurrency(categorySubtotals.Other)}</span>
            </div>
            <div className="space-y-4">
              {formData.otherEntries.map((entry, idx) => (
                <div key={entry.id} className="p-4 border border-gray-100 rounded-lg bg-gray-50 relative grid grid-cols-1 sm:grid-cols-2 gap-4">
                   <div className="space-y-1">
                      <label className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">Date</label>
                      <input type="date" value={entry.date} onChange={(e) => updateEntry('other', entry.id, 'date', e.target.value)} className="w-full bg-transparent border-b border-gray-300 py-1 focus:border-purple-600 outline-none text-sm" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">Amount (₹)</label>
                      <input type="number" placeholder="0.00" value={entry.amount} onChange={(e) => updateEntry('other', entry.id, 'amount', e.target.value)} className="w-full bg-transparent border-b border-gray-300 py-1 focus:border-purple-600 outline-none text-sm font-bold" />
                   </div>
                   <div className="sm:col-span-2">
                      <input type="file" onChange={(e) => updateEntry('other', entry.id, 'attachment', e.target.files?.[0])} className="text-[10px] text-gray-500 file:mr-2 file:py-1 file:px-3 file:rounded-full file:border-0 file:text-[10px] file:font-semibold file:bg-gray-200 file:text-gray-700" />
                   </div>
                   {formData.otherEntries.length > 1 && (
                     <button type="button" onClick={() => removeRow('other', entry.id)} className="absolute top-2 right-2 text-gray-300 hover:text-red-500">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                     </button>
                   )}
                </div>
              ))}
              <button type="button" onClick={() => addRow('other')} className="w-full py-2 border-2 border-dashed border-gray-200 rounded-lg text-gray-400 hover:text-gray-600 hover:border-gray-200 hover:bg-gray-100 transition-all text-sm font-medium">+ Add Other Detail</button>
            </div>
          </FormCard>
        )}

        {/* Summary Card */}
        {grandTotal > 0 && (
          <FormCard>
            <h2 className="text-xl font-bold text-gray-800 mb-4 border-b border-gray-100 pb-2">Summary of Expenses</h2>
            <div className="space-y-3">
              {formData.categories.map(cat => (
                <div key={cat} className="flex justify-between items-center text-sm">
                  <span className="text-gray-500 font-medium">{cat} Subtotal</span>
                  <span className="text-gray-900 font-bold">{formatCurrency(categorySubtotals[cat])}</span>
                </div>
              ))}
              <div className="border-t-2 border-double border-gray-200 pt-3 flex justify-between items-center">
                <span className="text-lg font-bold text-gray-900 uppercase tracking-tight">Grand Total</span>
                <span className="text-2xl font-black text-purple-700">{formatCurrency(grandTotal)}</span>
              </div>
            </div>
          </FormCard>
        )}

        {/* Remark Card */}
        <FormCard>
           <label className="block text-base font-medium text-gray-900 mb-2">Expenses Description / Purpose / Remark</label>
           <textarea 
            rows={4}
            value={formData.remark}
            onChange={(e) => setFormData({ ...formData, remark: e.target.value })}
            placeholder="Please explain the business reason for these expenses..."
            className="w-full border-b-2 border-gray-200 py-2 focus:border-purple-600 outline-none transition-all resize-none text-sm"
           />
        </FormCard>

        {/* Submit Actions */}
        <div className="flex flex-col sm:flex-row justify-between items-center pb-12 gap-4">
           <button 
            type="submit" 
            disabled={isSubmitting || grandTotal === 0}
            className={`w-full sm:w-auto px-12 py-3 rounded-lg text-white font-bold text-lg shadow-lg transition-all flex items-center justify-center gap-3 ${isSubmitting || grandTotal === 0 ? 'bg-gray-300 cursor-not-allowed shadow-none' : 'bg-purple-700 hover:bg-purple-800 hover:-translate-y-0.5 active:translate-y-0'}`}
           >
            {isSubmitting ? (
              <>
                <svg className="animate-spin h-5 w-5 text-white" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                Submitting...
              </>
            ) : 'Submit Expenses'}
           </button>
           <button type="button" onClick={() => confirm('Reset form?') && window.location.reload()} className="text-gray-400 hover:text-red-500 font-bold text-xs uppercase tracking-widest transition-colors">
            Clear all data
           </button>
        </div>
      </form>

      <footer className="text-center text-[10px] text-gray-400 pb-12 font-bold uppercase tracking-[0.2em]">
        Ginza Industries Limited &copy; {new Date().getFullYear()} • Finance & Accounting Dept.
      </footer>
    </div>
  );
};

