export const CATEGORIES: string[] = ['Travel', 'Food', 'Accommodation', 'Other'];

export const GINZA_LOGO_URL = 'https://www.ginzalimited.com/cdn/shop/files/Ginza_logo.jpg?v=1668509673&width=500';

import React, { useState, useMemo } from 'react';
import { FormCard } from './components/FormCard';
import { BRANCH_SALES_MAPPING, CATEGORIES, GINZA_LOGO_URL } from './constants';
import { FormData, ExpenseCategory } from './types';
import { submitToGoogleSheets } from './services/googleSheetsService';

const App: React.FC = () => {
  const [formData, setFormData] = useState<FormData>({
    expenseDate: new Date().toISOString().split('T')[0],
    branchName: '',
    salespersonName: '',
    categories: [],
    travelEntries: [],
    foodEntries: [],
    accommodationEntries: [],
    otherEntries: [],
    remark: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  // Financial Calculations
  const categorySubtotals = useMemo(() => {
    return {
      Travel: formData.travelEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
      Food: formData.foodEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
      Accommodation: formData.accommodationEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
      Other: formData.otherEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
    };
  }, [formData.travelEntries, formData.foodEntries, formData.accommodationEntries, formData.otherEntries]);

  const grandTotal = useMemo(() => {
    return Object.keys(categorySubtotals).reduce((sum, key) => {
      // Only add to grand total if the category is currently selected
      return formData.categories.includes(key as ExpenseCategory) 
        ? sum + categorySubtotals[key as keyof typeof categorySubtotals] 
        : sum;
    }, 0);
  }, [categorySubtotals, formData.categories]);

  const handleCategoryToggle = (category: ExpenseCategory) => {
    setFormData(prev => {
      const isSelected = prev.categories.includes(category);
      const newCategories = isSelected 
        ? prev.categories.filter(c => c !== category)
        : [...prev.categories, category];

      const updates: Partial<FormData> = { categories: newCategories };
      if (!isSelected) {
        const initialRow = { id: crypto.randomUUID(), date: prev.expenseDate, amount: '', attachment: null };
        if (category === 'Travel') updates.travelEntries = [{ ...initialRow, from: '', to: '' }];
        if (category === 'Food') updates.foodEntries = [initialRow];
        if (category === 'Accommodation') updates.accommodationEntries = [initialRow];
        if (category === 'Other') updates.otherEntries = [initialRow];
      }

      return { ...prev, ...updates };
    });
  };

  const addRow = (type: 'travel' | 'food' | 'accommodation' | 'other') => {
    setFormData(prev => {
      const common = { id: crypto.randomUUID(), date: prev.expenseDate, amount: '', attachment: null };
      if (type === 'travel') return { ...prev, travelEntries: [...prev.travelEntries, { ...common, from: '', to: '' }] };
      if (type === 'food') return { ...prev, foodEntries: [...prev.foodEntries, common] };
      if (type === 'accommodation') return { ...prev, accommodationEntries: [...prev.accommodationEntries, common] };
      return { ...prev, otherEntries: [...prev.otherEntries, common] };
    });
  };

  const updateEntry = (type: string, id: string, field: string, value: any) => {
    setFormData(prev => {
      const key = `${type}Entries` as keyof FormData;
      const list = prev[key] as any[];
      const newList = list.map(item => item.id === id ? { ...item, [field]: value } : item);
      return { ...prev, [key]: newList };
    });
  };

  const removeRow = (type: string, id: string) => {
    setFormData(prev => {
      const key = `${type}Entries` as keyof FormData;
      const list = prev[key] as any[];
      if (list.length <= 1) return prev; // Keep at least one row
      return { ...prev, [key]: list.filter(item => item.id !== id) };
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.branchName || !formData.salespersonName) {
      alert("Please fill in the Branch and Salesperson name.");
      return;
    }
    setIsSubmitting(true);
    const success = await submitToGoogleSheets(formData);
    setIsSubmitting(false);
    if (success) setIsSuccess(true);
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR' }).format(val);
  };

  if (isSuccess) {
    return (
      <div className="max-w-2xl mx-auto py-12 px-4">
        <FormCard isMain>
          <div className="flex justify-center mb-6">
             <img src={GINZA_LOGO_URL} alt="GINZA" className="h-16 object-contain" />
          </div>
          <h1 className="text-3xl font-normal mb-4 text-center">Expense Report Submitted</h1>
          <p className="text-gray-700 mb-6 text-center">Your response has been recorded successfully. Grand Total: <strong>{formatCurrency(grandTotal)}</strong></p>
          <div className="text-center">
            <button onClick={() => window.location.reload()} className="text-indigo-600 hover:underline text-sm font-medium">
              Submit another response
            </button>
          </div>
        </FormCard>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto py-8 px-4 sm:px-6">
      {/* Header Card */}
      <FormCard isMain>
        <div className="flex flex-col md:flex-row items-center gap-6 mb-6">
          <div className="flex-shrink-0">
             <img src={GINZA_LOGO_URL} alt="GINZA INDUSTRIES LIMITED" className="h-24 w-auto object-contain rounded-lg" />
          </div>
          <div className="text-center md:text-left">
            <h1 className="text-3xl font-black text-gray-900 leading-tight tracking-tight uppercase">GINZA INDUSTRIES LIMITED</h1>
            <p className="text-xs uppercase tracking-widest text-indigo-600 font-bold mb-1">Corporate Expense Portal</p>
            <div className="mt-2 bg-gray-50 p-3 rounded-lg border border-gray-100 shadow-sm">
               <p className="text-[11px] leading-relaxed font-medium text-gray-600">
                <strong>Address:</strong> Lotus Corporate Park, A-501/502, Western Urban Rd, Geetanjali Railway Colony, Laxmi Nagar, Goregaon, Mumbai, Maharashtra 400063
               </p>
            </div>
          </div>
        </div>
        <div className="border-t border-gray-100 pt-4">
          <p className="text-sm text-gray-500 font-medium italic text-center md:text-left">Please ensure all attached bills are clear and readable.</p>
        </div>
      </FormCard>

      <form onSubmit={handleSubmit} className="space-y-4">
        {/* Core Info */}
        <FormCard>
          <div className="space-y-6">
            <div>
              <label className="block text-base font-medium text-gray-900 mb-2">Expenses Date</label>
              <input type="date" readOnly value={formData.expenseDate} className="w-full sm:w-1/2 border-b-2 border-gray-200 py-2 focus:border-indigo-600 outline-none bg-gray-50 cursor-default font-mono" />
            </div>

            <div>
              <label className="block text-base font-medium text-gray-900 mb-2">Select Branch Name *</label>
              <select required value={formData.branchName} onChange={(e) => setFormData({ ...formData, branchName: e.target.value, salespersonName: '' })} className="w-full sm:w-1/2 border-b-2 border-gray-200 py-2 focus:border-indigo-600 outline-none bg-transparent">
                <option value="">Choose Branch</option>
                {Object.keys(BRANCH_SALES_MAPPING).map(branch => <option key={branch} value={branch}>{branch}</option>)}
              </select>
            </div>

            {formData.branchName && (
              <div className="animate-in fade-in duration-300">
                <label className="block text-base font-medium text-gray-900 mb-2">Salesperson Name *</label>
                <select required value={formData.salespersonName} onChange={(e) => setFormData({ ...formData, salespersonName: e.target.value })} className="w-full sm:w-1/2 border-b-2 border-gray-200 py-2 focus:border-indigo-600 outline-none bg-transparent">
                  <option value="">Choose Salesperson</option>
                  {BRANCH_SALES_MAPPING[formData.branchName].map(name => <option key={name} value={name}>{name}</option>)}
                </select>
              </div>
            )}
          </div>
        </FormCard>

        {/* Categories Selector */}
        <FormCard>
          <label className="block text-base font-medium text-gray-900 mb-4">Select Expense Categories</label>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
            {CATEGORIES.map(cat => (
