### Final Google Apps Script (Optimized)
Copy and paste this into your **Extensions > Apps Script** editor. 

**Note:** You must replace `'YOUR_DRIVE_FOLDER_ID_HERE'` with the ID of a folder in your Google Drive where you want the images saved.

```javascript
/**
 * GINZA INDUSTRIES LIMITED - EXPENSE TRACKER SCRIPT
 * Version: 2.0 (Handles multiple categories into single-row entries)
 */

const FOLDER_ID = 'YOUR_DRIVE_FOLDER_ID_HERE'; // <--- PASTE FOLDER ID HERE

function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const sheet = ss.getSheetByName("Expenses") || ss.insertSheet("Expenses");

    // Auto-create headers if sheet is empty
    if (sheet.getLastRow() === 0) {
      sheet.appendRow([
        "Timestamp", "Submission ID", "Branch Name", "Salesperson Name", 
        "Expense Category", "Item Date", "From Location", "To Location", 
        "Amount", "Attachment Link", "Remark", "Grand Total"
      ]);
      sheet.getRange(1, 1, 1, 12).setFontWeight("bold").setBackground("#f3f3f3");
    }

    const submissionId = "SUB-" + Utilities.getUuid().substring(0,8).toUpperCase();
    const timestamp = new Date();
    const folder = DriveApp.getFolderById(FOLDER_ID);

    // Calculate total amount once for the whole submission
    let totalClaimAmount = 0;
    ['travel', 'food', 'accommodation', 'other'].forEach(c => {
      (data[c + 'Entries'] || []).forEach(item => totalClaimAmount += (parseFloat(item.amount) || 0));
    });

    // Helper to process entries
    const processCategory = (categoryName, entries) => {
      entries.forEach(entry => {
        let fileUrl = "No Attachment";

        // Handle Base64 Attachment
        if (entry.attachment && entry.attachment.base64) {
          const blob = Utilities.newBlob(
            Utilities.base64Decode(entry.attachment.base64), 
            entry.attachment.mimeType, 
            categoryName + "_" + entry.attachment.name
          );
          const file = folder.createFile(blob);
          file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
          fileUrl = file.getUrl();
        }

        // Add the row
        sheet.appendRow([
          timestamp,
          submissionId,
          data.branchName,
          data.salespersonName,
          categoryName.toUpperCase(),
          entry.date,
          entry.from || "-", // Specific to travel
          entry.to || "-",   // Specific to travel
          entry.amount,
          fileUrl,
          data.remark,
          totalClaimAmount
        ]);
      });
    };

    // Run for all categories
    if (data.categories.includes('Travel')) processCategory('Travel', data.travelEntries);
    if (data.categories.includes('Food')) processCategory('Food', data.foodEntries);
    if (data.categories.includes('Accommodation')) processCategory('Accommodation', data.accommodationEntries);
    if (data.categories.includes('Other')) processCategory('Other', data.otherEntries);

    return ContentService.createTextOutput(JSON.stringify({ "result": "success", "id": submissionId }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({ "result": "error", "error": error.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}
