const App: React.FC = () => {
  const [formData, setFormData] = useState<FormData>({
    expenseDate: new Date().toISOString().split('T')[0],
    branchName: '',
    salespersonName: '',
    categories: [],
    travelEntries: [],
    foodEntries: [],
    accommodationEntries: [],
    otherEntries: [],
    remark: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const categorySubtotals = useMemo(() => {
    return {
      Travel: formData.travelEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
      Food: formData.foodEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
      Accommodation: formData.accommodationEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
      Other: formData.otherEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
    };
  }, [formData.travelEntries, formData.foodEntries, formData.accommodationEntries, formData.otherEntries]);

  const grandTotal = useMemo(() => {
    return Object.keys(categorySubtotals).reduce((sum, key) => {
      return formData.categories.includes(key as ExpenseCategory) 
        ? sum + categorySubtotals[key as keyof typeof categorySubtotals] 
        : sum;
    }, 0);
  }, [categorySubtotals, formData.categories]);

  const handleCategoryToggle = (category: ExpenseCategory) => {
    setFormData(prev => {
      const isSelected = prev.categories.includes(category);
      const newCategories = isSelected 
        ? prev.categories.filter(c => c !== category)
        : [...prev.categories, category];

      const updates: Partial<FormData> = { categories: newCategories };
      if (!isSelected) {
        const initialRow = { id: crypto.randomUUID(), date: prev.expenseDate, amount: '', attachment: null };
        if (category === 'Travel') updates.travelEntries = [{ ...initialRow, from: '', to: '' }];
        if (category === 'Food') updates.foodEntries = [initialRow];
        if (category === 'Accommodation') updates.accommodationEntries = [initialRow];
        if (category === 'Other') updates.otherEntries = [initialRow];
      } else {
        if (category === 'Travel') updates.travelEntries = [];
        if (category === 'Food') updates.foodEntries = [];
        if (category === 'Accommodation') updates.accommodationEntries = [];
        if (category === 'Other') updates.otherEntries = [];
      }
      return { ...prev, ...updates };
    });
  };

  const addRow = (type: 'travel' | 'food' | 'accommodation' | 'other') => {
    setFormData(prev => {
      const common = { id: crypto.randomUUID(), date: prev.expenseDate, amount: '', attachment: null };
      if (type === 'travel') return { ...prev, travelEntries: [...prev.travelEntries, { ...common, from: '', to: '' }] };
      if (type === 'food') return { ...prev, foodEntries: [...prev.foodEntries, common] };
      if (type === 'accommodation') return { ...prev, accommodationEntries: [...prev.accommodationEntries, common] };
      return { ...prev, otherEntries: [...prev.otherEntries, common] };
    });
  };

  const updateEntry = (type: string, id: string, field: string, value: any) => {
    setFormData(prev => {
      const key = `${type}Entries` as keyof FormData;
      const list = (prev[key] as any[]).map(item => item.id === id ? { ...item, [field]: value } : item);
      return { ...prev, [key]: list };
    });
  };

  const removeRow = (type: string, id: string) => {
    setFormData(prev => {
      const key = `${type}Entries` as keyof FormData;
      const list = prev[key] as any[];
      if (list.length <= 1) return prev; 
      return { ...prev, [key]: list.filter(item => item.id !== id) };
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.branchName || !formData.salespersonName) {
      alert("Please select Branch and Salesperson name first.");
      return;
    }
    setIsSubmitting(true);
    const success = await submitToGoogleSheets(formData);
    setIsSubmitting(false);
    if (success) {
      setIsSuccess(true);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
      alert("Submission failed. Check your network or script deployment.");
    }
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR' }).format(val);
  };

  if (isSuccess) {
    return (
      <div className="max-w-2xl mx-auto py-12 px-4 animate-in fade-in duration-700">
        <FormCard isMain>
          <div className="flex justify-center mb-10">
             <img src={GINZA_LOGO_URL} alt="GINZA" className="h-24 object-contain" />
          </div>
          <h1 className="text-4xl font-black mb-6 text-center text-gray-900 uppercase tracking-tighter">Response Recorded</h1>
          <p className="text-center text-gray-500 font-bold mb-10 uppercase tracking-widest text-xs">Thank you. Your expense report has been sent for review.</p>
          <div className="bg-indigo-50 p-12 rounded-[3rem] border-4 border-indigo-100 mb-10 text-center shadow-2xl">
            <span className="text-[12px] font-black text-indigo-400 uppercase tracking-[0.4em] block mb-4">Total Reimbursement Claimed</span>
            <span className="text-6xl font-black text-indigo-900 tracking-tighter">{formatCurrency(grandTotal)}</span>
          </div>
          <div className="text-center">
            <button onClick={() => window.location.reload()} className="bg-indigo-600 text-white px-16 py-6 rounded-full font-black text-sm uppercase tracking-[0.2em] hover:bg-indigo-700 transition-all shadow-xl active:scale-95">
              Submit Another Response
            </button>
          </div>
        </FormCard>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto py-8 px-4 sm:px-6">
      {/* Dynamic Header Section */}
      <div className="bg-white rounded-lg shadow-sm mb-6 border border-gray-200 overflow-hidden google-form-card">
        <div className="h-64 w-full relative">
          <img 
            src="https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&q=80&w=1200" 
            alt="Corporate Header" 
            className="w-full h-full object-cover grayscale brightness-[0.2]"
          />
          <div className="absolute inset-0 flex flex-col items-center justify-center p-6 text-center">
            <div className="bg-white p-5 rounded-[2rem] shadow-2xl mb-6 transform hover:scale-105 transition-all">
               <img src={GINZA_LOGO_URL} alt="GINZA" className="h-24 w-auto object-contain" />
            </div>
            <h1 className="text-2xl sm:text-4xl font-black text-white leading-tight tracking-tighter uppercase drop-shadow-2xl">
              GINZA INDUSTRIES LIMITED
            </h1>
            <p className="text-[12px] sm:text-sm uppercase tracking-[0.6em] text-indigo-400 font-black mt-4 drop-shadow-lg">
              Authorized Expense Portal
            </p>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Branch & Personnel Section */}
        <FormCard>
          <div className="space-y-12">
            <div>
              <label className="block text-[15px] font-black text-gray-900 uppercase tracking-[0.15em] mb-4">
                Expense Date
              </label>
              <input type="date" readOnly value={formData.expenseDate} className="w-full sm:w-1/2 border-b-4 border-gray-100 py-4 outline-none bg-gray-50/50 font-mono text-base font-black text-gray-900 px-5 rounded-t-2xl shadow-inner" />
            </div>

            <div>
              <label className="block text-[15px] font-black text-gray-900 uppercase tracking-[0.15em] mb-4">
                Select Branch Name *
              </label>
              <select required value={formData.branchName} onChange={(e) => setFormData({ ...formData, branchName: e.target.value, salespersonName: '' })} className="w-full sm:w-1/2 border-b-4 border-gray-100 py-4 focus:border-indigo-600 outline-none bg-transparent text-base font-black text-indigo-900 cursor-pointer appearance-none hover:bg-gray-50 px-5 rounded-t-2xl transition-all shadow-sm">
                <option value="">-- CHOOSE BRANCH --</option>
                {Object.keys(BRANCH_SALES_MAPPING).map(branch => <option key={branch} value={branch}>{branch}</option>)}
              </select>
            </div>

            {formData.branchName && (
              <div className="animate-in fade-in slide-in-from-top-4 duration-500">
                <label className="block text-[15px] font-black text-gray-900 uppercase tracking-[0.15em] mb-4">
                  Salesperson Name *
                </label>
                <select required value={formData.salespersonName} onChange={(e) => setFormData({ ...formData, salespersonName: e.target.value })} className="w-full sm:w-1/2 border-b-4 border-gray-100 py-4 focus:border-indigo-600 outline-none bg-transparent text-base font-black text-indigo-900 cursor-pointer appearance-none hover:bg-gray-50 px-5 rounded-t-2xl transition-all shadow-sm">
                  <option value="">-- CHOOSE SALESPERSON --</option>
                  {BRANCH_SALES_MAPPING[formData.branchName].map(name => <option key={name} value={name}>{name}</option>)}
                </select>
              </div>
            )}
          </div>
        </FormCard>

        {/* Category Picker Section */}
        <FormCard>
          <label className="block text-[15px] font-black text-gray-900 uppercase tracking-[0.2em] mb-10 text-center">
            Expense Categories Selection
          </label>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-6">
            {CATEGORIES.map(cat => (
              <label key={cat} className={`flex flex-col items-center justify-center gap-5 cursor-pointer p-8 rounded-[3rem] border-2 transition-all duration-300 text-center ${formData.categories.includes(cat as ExpenseCategory) ? 'border-indigo-600 bg-indigo-50 shadow-2xl ring-4 ring-indigo-100 scale-105' : 'border-gray-50 hover:bg-gray-50 hover:border-gray-200 shadow-sm'}`}>
                <input type="checkbox" checked={formData.categories.includes(cat as ExpenseCategory)} onChange={() => handleCategoryToggle(cat as ExpenseCategory)} className="hidden" />
                <div className={`text-6xl transition-all transform ${formData.categories.includes(cat as ExpenseCategory) ? 'grayscale-0 rotate-3' : 'grayscale opacity-20'}`}>
                  {cat === 'Travel' && '🚗'}
                  {cat === 'Food' && '🍱'}
                  {cat === 'Accommodation' && '🏢'}
                  {cat === 'Other' && '📁'}
                </div>
                <span className={`text-[13px] font-black tracking-[0.1em] uppercase ${formData.categories.includes(cat as ExpenseCategory) ? 'text-indigo-900' : 'text-gray-400'}`}>{cat}</span>
              </label>
            ))}
          </div>
        </FormCard>

        {/* Travel Log Section */}
        {formData.categories.includes('Travel') && (
          <FormCard>
            <div className="flex justify-between items-center mb-12 border-b-4 border-gray-100 pb-6">
              <h2 className="text-2xl font-black text-gray-900 uppercase tracking-tighter">🚗 Travel Registry</h2>
              <span className="text-[13px] font-black text-white bg-indigo-600 px-8 py-3 rounded-full shadow-2xl">{formatCurrency(categorySubtotals.Travel)}</span>
            </div>
            <div className="space-y-16">
              {formData.travelEntries.map((entry) => (
                <div key={entry.id} className="p-10 border-2 border-gray-100 rounded-[3.5rem] bg-gray-50/30 relative group transition-all hover:bg-white hover:shadow-2xl">
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-10">
                      <div>
                        <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Expense Date</label>
                        <input type="date" value={entry.date} onChange={(e) => updateEntry('travel', entry.id, 'date', e.target.value)} className="w-full bg-white border-2 border-gray-100 rounded-[1.5rem] px-6 py-4 focus:ring-4 focus:ring-indigo-100 focus:border-indigo-600 outline-none text-base font-black shadow-sm" />
                      </div>
                      <div>
                        <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Origin (From)</label>
                        <input type="text" placeholder="Start Point" value={entry.from} onChange={(e) => updateEntry('travel', entry.id, 'from', e.target.value)} className="w-full bg-white border-2 border-gray-100 rounded-[1.5rem] px-6 py-4 focus:ring-4 focus:ring-indigo-100 focus:border-indigo-600 outline-none text-base font-black shadow-sm" />
                      </div>
                      <div>
                        <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Destination (To)</label>
                        <input type="text" placeholder="End Point" value={entry.to} onChange={(e) => updateEntry('travel', entry.id, 'to', e.target.value)} className="w-full bg-white border-2 border-gray-100 rounded-[1.5rem] px-6 py-4 focus:ring-4 focus:ring-indigo-100 focus:border-indigo-600 outline-none text-base font-black shadow-sm" />
                      </div>
                      <div>
                        <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Amount (₹)</label>
                        <input type="number" placeholder="0.00" value={entry.amount} onChange={(e) => updateEntry('travel', entry.id, 'amount', e.target.value)} className="w-full bg-white border-2 border-gray-100 rounded-[1.5rem] px-6 py-4 focus:ring-4 focus:ring-indigo-100 focus:border-indigo-600 outline-none text-base font-black text-indigo-900 shadow-sm" />
                      </div>
                      <div className="md:col-span-2">
                        <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Proof Attachment</label>
                        <div className="flex items-center gap-6 bg-white p-5 rounded-[1.5rem] border-2 border-dashed border-indigo-100 hover:border-indigo-500 transition-all cursor-pointer">
                          <input type="file" onChange={(e) => updateEntry('travel', entry.id, 'attachment', e.target.files?.[0])} className="text-[12px] text-gray-900 font-black file:mr-8 file:py-3 file:px-12 file:rounded-xl file:border-0 file:text-[12px] file:font-black file:bg-indigo-50 file:text-indigo-600 hover:file:bg-indigo-600 hover:file:text-white cursor-pointer w-full" />
                          {entry.attachment && <span className="text-[12px] font-black text-green-600 bg-green-50 px-6 py-2 rounded-xl whitespace-nowrap shadow-sm border border-green-100">✅ ATTACHED</span>}
                        </div>
                      </div>
                   </div>
                   {formData.travelEntries.length > 1 && (
                     <button type="button" onClick={() => removeRow('travel', entry.id)} className="absolute -top-6 -right-6 bg-white text-gray-300 hover:text-red-500 shadow-2xl border-2 border-gray-50 rounded-full p-5 transition-all hover:scale-110 z-10 active:scale-90">
                        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M6 18L18 6M6 6l12 12" /></svg>
                     </button>
                   )}
                </div>
              ))}
              <button type="button" onClick={() => addRow('travel')} className="w-full py-10 border-4 border-dashed border-gray-100 rounded-[4rem] text-gray-400 hover:text-indigo-600 hover:border-indigo-300 hover:bg-indigo-50 transition-all font-black text-[15px] uppercase tracking-[0.5em] flex justify-center items-center gap-8 shadow-sm active:translate-y-1">
                <span className="text-5xl">+</span> NEW TRAVEL ROW
              </button>
            </div>
          </FormCard>
        )}

        {/* Dynamic Billing Sections (Food, Accommodation, Other) */}
        {['Food', 'Accommodation', 'Other'].map(type => {
          const cat = type as ExpenseCategory;
          if (!formData.categories.includes(cat)) return null;
          const entriesKey = `${type.toLowerCase()}Entries` as keyof FormData;
          const entries = formData[entriesKey] as any[];
          const colorClass = type === 'Food' ? 'orange-600' : type === 'Accommodation' ? 'blue-600' : 'emerald-600';
          const icon = type === 'Food' ? '🍱' : type === 'Accommodation' ? '🏢' : '📁';

          return (
            <FormCard key={type}>
              <div className="flex justify-between items-center mb-12 border-b-4 border-gray-100 pb-6">
                <h2 className="text-2xl font-black text-gray-900 uppercase tracking-tighter">{icon} {type.toUpperCase()} BILLS</h2>
                <span className={`text-[13px] font-black text-white bg-${colorClass} px-8 py-3 rounded-full shadow-2xl`}>{formatCurrency(categorySubtotals[cat as keyof typeof categorySubtotals])}</span>
              </div>
              <div className="space-y-16">
                {entries.map((entry) => (
                  <div key={entry.id} className="p-10 border-2 border-gray-100 rounded-[3.5rem] bg-gray-50/30 relative group transition-all hover:bg-white hover:shadow-2xl">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                       <div>
                          <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Expense Date</label>
                          <input type="date" value={entry.date} onChange={(e) => updateEntry(type.toLowerCase(), entry.id, 'date', e.target.value)} className="w-full bg-white border-2 border-gray-100 rounded-[1.5rem] px-6 py-4 focus:ring-4 focus:ring-indigo-100 outline-none text-base font-black shadow-sm" />
                       </div>
                       <div>
                          <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Amount (₹)</label>
                          <input type="number" placeholder="0.00" value={entry.amount} onChange={(e) => updateEntry(type.toLowerCase(), entry.id, 'amount', e.target.value)} className="w-full bg-white border-2 border-gray-100 rounded-[1.5rem] px-6 py-4 focus:ring-4 focus:ring-indigo-100 outline-none text-base font-black text-gray-900 shadow-sm" />
                       </div>
                       <div className="md:col-span-2">
                          <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Attachment Scan</label>
                          <div className="flex items-center gap-6 bg-white p-5 rounded-[1.5rem] border-2 border-dashed border-gray-200 hover:border-indigo-500 transition-all">
                            <input type="file" onChange={(e) => updateEntry(type.toLowerCase(), entry.id, 'attachment', e.target.files?.[0])} className="text-[12px] text-gray-900 font-black file:mr-8 file:py-3 file:px-12 file:rounded-xl file:border-0 file:text-[12px] file:font-black file:bg-gray-100 file:text-gray-600 hover:file:bg-indigo-600 hover:file:text-white cursor-pointer w-full" />
                            {entry.attachment && <span className="text-[12px] font-black text-green-600 bg-green-50 px-6 py-2 rounded-xl whitespace-nowrap shadow-sm border border-green-100">✅ ATTACHED</span>}
                          </div>
                       </div>
                    </div>
                    {entries.length > 1 && (
                      <button type="button" onClick={() => removeRow(type.toLowerCase(), entry.id)} className="absolute -top-6 -right-6 bg-white text-gray-300 hover:text-red-500 shadow-2xl border-2 border-gray-100 rounded-full p-5 transition-all z-10 active:scale-90">
                        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M6 18L18 6M6 6l12 12" /></svg>
                      </button>
                    )}
                  </div>
                ))}
                <button type="button" onClick={() => addRow(type.toLowerCase() as any)} className="w-full py-10 border-4 border-dashed border-gray-100 rounded-[4rem] text-gray-400 hover:text-indigo-600 hover:border-indigo-300 hover:bg-indigo-50 transition-all font-black text-[15px] uppercase tracking-[0.5em] flex justify-center items-center gap-8 shadow-sm active:translate-y-1">
                  <span className="text-5xl">+</span> ADD {type.toUpperCase()} ROW
                </button>
              </div>
            </FormCard>
          );
        })}

        {/* Remarks Section */}
        <FormCard>
           <label className="block text-[15px] font-black text-gray-900 uppercase tracking-widest mb-6 ml-1 flex items-center gap-5">
             <div className="bg-indigo-100 p-3 rounded-2xl shadow-sm">
               <svg className="w-8 h-8 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z"/></svg>
             </div>
             Expense Remarks / Purpose
           </label>
           <textarea 
            rows={6}
            value={formData.remark}
            onChange={(e) => setFormData({ ...formData, remark: e.target.value })}
            placeholder="Describe the business purpose of these expenses in detail..."
            className="w-full bg-gray-50/50 border-4 border-transparent border-b-gray-100 py-10 px-10 focus:border-indigo-600 focus:bg-white outline-none transition-all resize-none text-base font-black rounded-t-[4rem] shadow-inner placeholder-gray-300"
           />
        </FormCard>

        {/* Submit Actions */}
        <div className="flex flex-col sm:flex-row justify-between items-center pb-40 gap-16 mt-16">
           <button 
            type="submit" 
            disabled={isSubmitting || grandTotal === 0}
            className={`w-full sm:w-auto px-40 py-12 rounded-[6rem] text-white font-black text-4xl shadow-2xl transition-all duration-300 flex items-center justify-center gap-12 ${isSubmitting || grandTotal === 0 ? 'bg-gray-200 cursor-not-allowed text-gray-400 shadow-none' : 'bg-indigo-600 hover:bg-indigo-700 hover:-translate-y-3 active:scale-95 shadow-indigo-300/80'}`}
           >
            {isSubmitting ? (
              <>
                <svg className="animate-spin h-12 w-12 text-white" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                SAVING...
              </>
            ) : (
              <>
                SUBMIT
                <svg className="w-16 h-16 opacity-40" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
              </>
            )}
           </button>
           <button 
             type="button" 
             onClick={() => confirm('Discard current draft?') && window.location.reload()} 
             className="text-gray-400 hover:text-red-600 font-black text-[15px] uppercase tracking-[0.8em] transition-all flex items-center gap-10 group px-16 py-8 hover:bg-red-50 rounded-full"
           >
             <svg className="w-12 h-12 transition-transform group-hover:rotate-180 duration-1000" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
             CLEAR
           </button>
        </div>
      </form>

      <footer className="text-center pb-32 opacity-80 border-t-8 border-gray-100 pt-32 px-12">
           <p className="text-[22px] text-gray-900 font-black uppercase tracking-[1.5em] mb-8">
             Ginza Industries Limited
           </p>
           <p className="text-[14px] text-gray-400 font-bold uppercase tracking-[0.6em]">
             Authorized Finance & Management Portal &copy; {new Date().getFullYear()}
           </p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { FormCard } from './components/FormCard';
import { BRANCH_SALES_MAPPING, CATEGORIES, GINZA_LOGO_URL } from './constants';
import { FormData, ExpenseCategory } from './types';
import { submitToGoogleSheets } from './services/googleSheetsService';

const App: React.FC = () => {
  const [formData, setFormData] = useState<FormData>({
    expenseDate: new Date().toISOString().split('T')[0],
    branchName: '',
    salespersonName: '',
    categories: [],
    travelEntries: [],
    foodEntries: [],
    accommodationEntries: [],
    otherEntries: [],
    remark: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const categorySubtotals = useMemo(() => {
    return {
      Travel: formData.travelEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
      Food: formData.foodEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
      Accommodation: formData.accommodationEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
      Other: formData.otherEntries.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0),
    };
  }, [formData.travelEntries, formData.foodEntries, formData.accommodationEntries, formData.otherEntries]);

  const grandTotal = useMemo(() => {
    return Object.keys(categorySubtotals).reduce((sum, key) => {
      return formData.categories.includes(key as ExpenseCategory) 
        ? sum + categorySubtotals[key as keyof typeof categorySubtotals] 
        : sum;
    }, 0);
  }, [categorySubtotals, formData.categories]);

  const handleCategoryToggle = (category: ExpenseCategory) => {
    setFormData(prev => {
      const isSelected = prev.categories.includes(category);
      const newCategories = isSelected 
        ? prev.categories.filter(c => c !== category)
        : [...prev.categories, category];

      const updates: Partial<FormData> = { categories: newCategories };
      if (!isSelected) {
        const initialRow = { id: crypto.randomUUID(), date: prev.expenseDate, amount: '', attachment: null };
        if (category === 'Travel') updates.travelEntries = [{ ...initialRow, from: '', to: '' }];
        if (category === 'Food') updates.foodEntries = [initialRow];
        if (category === 'Accommodation') updates.accommodationEntries = [initialRow];
        if (category === 'Other') updates.otherEntries = [initialRow];
      } else {
        if (category === 'Travel') updates.travelEntries = [];
        if (category === 'Food') updates.foodEntries = [];
        if (category === 'Accommodation') updates.accommodationEntries = [];
        if (category === 'Other') updates.otherEntries = [];
      }
      return { ...prev, ...updates };
    });
  };

  const addRow = (type: 'travel' | 'food' | 'accommodation' | 'other') => {
    setFormData(prev => {
      const common = { id: crypto.randomUUID(), date: prev.expenseDate, amount: '', attachment: null };
      if (type === 'travel') return { ...prev, travelEntries: [...prev.travelEntries, { ...common, from: '', to: '' }] };
      if (type === 'food') return { ...prev, foodEntries: [...prev.foodEntries, common] };
      if (type === 'accommodation') return { ...prev, accommodationEntries: [...prev.accommodationEntries, common] };
      return { ...prev, otherEntries: [...prev.otherEntries, common] };
    });
  };

  const updateEntry = (type: string, id: string, field: string, value: any) => {
    setFormData(prev => {
      const key = `${type}Entries` as keyof FormData;
      const list = (prev[key] as any[]).map(item => item.id === id ? { ...item, [field]: value } : item);
      return { ...prev, [key]: list };
    });
  };

  const removeRow = (type: string, id: string) => {
    setFormData(prev => {
      const key = `${type}Entries` as keyof FormData;
      const list = prev[key] as any[];
      if (list.length <= 1) return prev; 
      return { ...prev, [key]: list.filter(item => item.id !== id) };
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.branchName || !formData.salespersonName) {
      alert("Please select Branch and Salesperson name first.");
      return;
    }
    setIsSubmitting(true);
    const success = await submitToGoogleSheets(formData);
    setIsSubmitting(false);
    if (success) {
      setIsSuccess(true);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
      alert("Submission failed. Check your network or script deployment.");
    }
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR' }).format(val);
  };

  if (isSuccess) {
    return (
      <div className="max-w-2xl mx-auto py-12 px-4 animate-in fade-in duration-700">
        <FormCard isMain>
          <div className="flex justify-center mb-10">
             <img src={GINZA_LOGO_URL} alt="GINZA" className="h-24 object-contain" />
          </div>
          <h1 className="text-4xl font-black mb-6 text-center text-gray-900 uppercase tracking-tighter">Response Recorded</h1>
          <p className="text-center text-gray-500 font-bold mb-10 uppercase tracking-widest text-xs">Thank you. Your expense report has been sent for review.</p>
          <div className="bg-indigo-50 p-12 rounded-[3rem] border-4 border-indigo-100 mb-10 text-center shadow-2xl">
            <span className="text-[12px] font-black text-indigo-400 uppercase tracking-[0.4em] block mb-4">Total Reimbursement Claimed</span>
            <span className="text-6xl font-black text-indigo-900 tracking-tighter">{formatCurrency(grandTotal)}</span>
          </div>
          <div className="text-center">
            <button onClick={() => window.location.reload()} className="bg-indigo-600 text-white px-16 py-6 rounded-full font-black text-sm uppercase tracking-[0.2em] hover:bg-indigo-700 transition-all shadow-xl active:scale-95">
              Submit Another Response
            </button>
          </div>
        </FormCard>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto py-8 px-4 sm:px-6">
      {/* Dynamic Header Section */}
      <div className="bg-white rounded-lg shadow-sm mb-6 border border-gray-200 overflow-hidden google-form-card">
        <div className="h-64 w-full relative">
          <img 
            src="https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&q=80&w=1200" 
            alt="Corporate Header" 
            className="w-full h-full object-cover grayscale brightness-[0.2]"
          />
          <div className="absolute inset-0 flex flex-col items-center justify-center p-6 text-center">
            <div className="bg-white p-5 rounded-[2rem] shadow-2xl mb-6 transform hover:scale-105 transition-all">
               <img src={GINZA_LOGO_URL} alt="GINZA" className="h-24 w-auto object-contain" />
            </div>
            <h1 className="text-2xl sm:text-4xl font-black text-white leading-tight tracking-tighter uppercase drop-shadow-2xl">
              GINZA INDUSTRIES LIMITED
            </h1>
            <p className="text-[12px] sm:text-sm uppercase tracking-[0.6em] text-indigo-400 font-black mt-4 drop-shadow-lg">
              Authorized Expense Portal
            </p>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Branch & Personnel Section */}
        <FormCard>
          <div className="space-y-12">
            <div>
              <label className="block text-[15px] font-black text-gray-900 uppercase tracking-[0.15em] mb-4">
                Expense Date
              </label>
              <input type="date" readOnly value={formData.expenseDate} className="w-full sm:w-1/2 border-b-4 border-gray-100 py-4 outline-none bg-gray-50/50 font-mono text-base font-black text-gray-900 px-5 rounded-t-2xl shadow-inner" />
            </div>

            <div>
              <label className="block text-[15px] font-black text-gray-900 uppercase tracking-[0.15em] mb-4">
                Select Branch Name *
              </label>
              <select required value={formData.branchName} onChange={(e) => setFormData({ ...formData, branchName: e.target.value, salespersonName: '' })} className="w-full sm:w-1/2 border-b-4 border-gray-100 py-4 focus:border-indigo-600 outline-none bg-transparent text-base font-black text-indigo-900 cursor-pointer appearance-none hover:bg-gray-50 px-5 rounded-t-2xl transition-all shadow-sm">
                <option value="">-- CHOOSE BRANCH --</option>
                {Object.keys(BRANCH_SALES_MAPPING).map(branch => <option key={branch} value={branch}>{branch}</option>)}
              </select>
            </div>

            {formData.branchName && (
              <div className="animate-in fade-in slide-in-from-top-4 duration-500">
                <label className="block text-[15px] font-black text-gray-900 uppercase tracking-[0.15em] mb-4">
                  Salesperson Name *
                </label>
                <select required value={formData.salespersonName} onChange={(e) => setFormData({ ...formData, salespersonName: e.target.value })} className="w-full sm:w-1/2 border-b-4 border-gray-100 py-4 focus:border-indigo-600 outline-none bg-transparent text-base font-black text-indigo-900 cursor-pointer appearance-none hover:bg-gray-50 px-5 rounded-t-2xl transition-all shadow-sm">
                  <option value="">-- CHOOSE SALESPERSON --</option>
                  {BRANCH_SALES_MAPPING[formData.branchName].map(name => <option key={name} value={name}>{name}</option>)}
                </select>
              </div>
            )}
          </div>
        </FormCard>

        {/* Category Picker Section */}
        <FormCard>
          <label className="block text-[15px] font-black text-gray-900 uppercase tracking-[0.2em] mb-10 text-center">
            Expense Categories Selection
          </label>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-6">
            {CATEGORIES.map(cat => (
              <label key={cat} className={`flex flex-col items-center justify-center gap-5 cursor-pointer p-8 rounded-[3rem] border-2 transition-all duration-300 text-center ${formData.categories.includes(cat as ExpenseCategory) ? 'border-indigo-600 bg-indigo-50 shadow-2xl ring-4 ring-indigo-100 scale-105' : 'border-gray-50 hover:bg-gray-50 hover:border-gray-200 shadow-sm'}`}>
                <input type="checkbox" checked={formData.categories.includes(cat as ExpenseCategory)} onChange={() => handleCategoryToggle(cat as ExpenseCategory)} className="hidden" />
                <div className={`text-6xl transition-all transform ${formData.categories.includes(cat as ExpenseCategory) ? 'grayscale-0 rotate-3' : 'grayscale opacity-20'}`}>
                  {cat === 'Travel' && '🚗'}
                  {cat === 'Food' && '🍱'}
                  {cat === 'Accommodation' && '🏢'}
                  {cat === 'Other' && '📁'}
                </div>
                <span className={`text-[13px] font-black tracking-[0.1em] uppercase ${formData.categories.includes(cat as ExpenseCategory) ? 'text-indigo-900' : 'text-gray-400'}`}>{cat}</span>
              </label>
            ))}
          </div>
        </FormCard>

        {/* Travel Log Section */}
        {formData.categories.includes('Travel') && (
          <FormCard>
            <div className="flex justify-between items-center mb-12 border-b-4 border-gray-100 pb-6">
              <h2 className="text-2xl font-black text-gray-900 uppercase tracking-tighter">🚗 Travel Registry</h2>
              <span className="text-[13px] font-black text-white bg-indigo-600 px-8 py-3 rounded-full shadow-2xl">{formatCurrency(categorySubtotals.Travel)}</span>
            </div>
            <div className="space-y-16">
              {formData.travelEntries.map((entry) => (
                <div key={entry.id} className="p-10 border-2 border-gray-100 rounded-[3.5rem] bg-gray-50/30 relative group transition-all hover:bg-white hover:shadow-2xl">
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-10">
                      <div>
                        <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Expense Date</label>
                        <input type="date" value={entry.date} onChange={(e) => updateEntry('travel', entry.id, 'date', e.target.value)} className="w-full bg-white border-2 border-gray-100 rounded-[1.5rem] px-6 py-4 focus:ring-4 focus:ring-indigo-100 focus:border-indigo-600 outline-none text-base font-black shadow-sm" />
                      </div>
                      <div>
                        <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Origin (From)</label>
                        <input type="text" placeholder="Start Point" value={entry.from} onChange={(e) => updateEntry('travel', entry.id, 'from', e.target.value)} className="w-full bg-white border-2 border-gray-100 rounded-[1.5rem] px-6 py-4 focus:ring-4 focus:ring-indigo-100 focus:border-indigo-600 outline-none text-base font-black shadow-sm" />
                      </div>
                      <div>
                        <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Destination (To)</label>
                        <input type="text" placeholder="End Point" value={entry.to} onChange={(e) => updateEntry('travel', entry.id, 'to', e.target.value)} className="w-full bg-white border-2 border-gray-100 rounded-[1.5rem] px-6 py-4 focus:ring-4 focus:ring-indigo-100 focus:border-indigo-600 outline-none text-base font-black shadow-sm" />
                      </div>
                      <div>
                        <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Amount (₹)</label>
                        <input type="number" placeholder="0.00" value={entry.amount} onChange={(e) => updateEntry('travel', entry.id, 'amount', e.target.value)} className="w-full bg-white border-2 border-gray-100 rounded-[1.5rem] px-6 py-4 focus:ring-4 focus:ring-indigo-100 focus:border-indigo-600 outline-none text-base font-black text-indigo-900 shadow-sm" />
                      </div>
                      <div className="md:col-span-2">
                        <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Proof Attachment</label>
                        <div className="flex items-center gap-6 bg-white p-5 rounded-[1.5rem] border-2 border-dashed border-indigo-100 hover:border-indigo-500 transition-all cursor-pointer">
                          <input type="file" onChange={(e) => updateEntry('travel', entry.id, 'attachment', e.target.files?.[0])} className="text-[12px] text-gray-900 font-black file:mr-8 file:py-3 file:px-12 file:rounded-xl file:border-0 file:text-[12px] file:font-black file:bg-indigo-50 file:text-indigo-600 hover:file:bg-indigo-600 hover:file:text-white cursor-pointer w-full" />
                          {entry.attachment && <span className="text-[12px] font-black text-green-600 bg-green-50 px-6 py-2 rounded-xl whitespace-nowrap shadow-sm border border-green-100">✅ ATTACHED</span>}
                        </div>
                      </div>
                   </div>
                   {formData.travelEntries.length > 1 && (
                     <button type="button" onClick={() => removeRow('travel', entry.id)} className="absolute -top-6 -right-6 bg-white text-gray-300 hover:text-red-500 shadow-2xl border-2 border-gray-50 rounded-full p-5 transition-all hover:scale-110 z-10 active:scale-90">
                        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M6 18L18 6M6 6l12 12" /></svg>
                     </button>
                   )}
                </div>
              ))}
              <button type="button" onClick={() => addRow('travel')} className="w-full py-10 border-4 border-dashed border-gray-100 rounded-[4rem] text-gray-400 hover:text-indigo-600 hover:border-indigo-300 hover:bg-indigo-50 transition-all font-black text-[15px] uppercase tracking-[0.5em] flex justify-center items-center gap-8 shadow-sm active:translate-y-1">
                <span className="text-5xl">+</span> NEW TRAVEL ROW
              </button>
            </div>
          </FormCard>
        )}

        {/* Dynamic Billing Sections (Food, Accommodation, Other) */}
        {['Food', 'Accommodation', 'Other'].map(type => {
          const cat = type as ExpenseCategory;
          if (!formData.categories.includes(cat)) return null;
          const entriesKey = `${type.toLowerCase()}Entries` as keyof FormData;
          const entries = formData[entriesKey] as any[];
          const colorClass = type === 'Food' ? 'orange-600' : type === 'Accommodation' ? 'blue-600' : 'emerald-600';
          const icon = type === 'Food' ? '🍱' : type === 'Accommodation' ? '🏢' : '📁';

          return (
            <FormCard key={type}>
              <div className="flex justify-between items-center mb-12 border-b-4 border-gray-100 pb-6">
                <h2 className="text-2xl font-black text-gray-900 uppercase tracking-tighter">{icon} {type.toUpperCase()} BILLS</h2>
                <span className={`text-[13px] font-black text-white bg-${colorClass} px-8 py-3 rounded-full shadow-2xl`}>{formatCurrency(categorySubtotals[cat as keyof typeof categorySubtotals])}</span>
              </div>
              <div className="space-y-16">
                {entries.map((entry) => (
                  <div key={entry.id} className="p-10 border-2 border-gray-100 rounded-[3.5rem] bg-gray-50/30 relative group transition-all hover:bg-white hover:shadow-2xl">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                       <div>
                          <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Expense Date</label>
                          <input type="date" value={entry.date} onChange={(e) => updateEntry(type.toLowerCase(), entry.id, 'date', e.target.value)} className="w-full bg-white border-2 border-gray-100 rounded-[1.5rem] px-6 py-4 focus:ring-4 focus:ring-indigo-100 outline-none text-base font-black shadow-sm" />
                       </div>
                       <div>
                          <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Amount (₹)</label>
                          <input type="number" placeholder="0.00" value={entry.amount} onChange={(e) => updateEntry(type.toLowerCase(), entry.id, 'amount', e.target.value)} className="w-full bg-white border-2 border-gray-100 rounded-[1.5rem] px-6 py-4 focus:ring-4 focus:ring-indigo-100 outline-none text-base font-black text-gray-900 shadow-sm" />
                       </div>
                       <div className="md:col-span-2">
                          <label className="text-[14px] font-black text-gray-900 uppercase tracking-widest mb-4 block">Attachment Scan</label>
                          <div className="flex items-center gap-6 bg-white p-5 rounded-[1.5rem] border-2 border-dashed border-gray-200 hover:border-indigo-500 transition-all">
                            <input type="file" onChange={(e) => updateEntry(type.toLowerCase(), entry.id, 'attachment', e.target.files?.[0])} className="text-[12px] text-gray-900 font-black file:mr-8 file:py-3 file:px-12 file:rounded-xl file:border-0 file:text-[12px] file:font-black file:bg-gray-100 file:text-gray-600 hover:file:bg-indigo-600 hover:file:text-white cursor-pointer w-full" />
                            {entry.attachment && <span className="text-[12px] font-black text-green-600 bg-green-50 px-6 py-2 rounded-xl whitespace-nowrap shadow-sm border border-green-100">✅ ATTACHED</span>}
                          </div>
                       </div>
                    </div>
                    {entries.length > 1 && (
                      <button type="button" onClick={() => removeRow(type.toLowerCase(), entry.id)} className="absolute -top-6 -right-6 bg-white text-gray-300 hover:text-red-500 shadow-2xl border-2 border-gray-100 rounded-full p-5 transition-all z-10 active:scale-90">
                        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M6 18L18 6M6 6l12 12" /></svg>
                      </button>
                    )}
                  </div>
                ))}
                <button type="button" onClick={() => addRow(type.toLowerCase() as any)} className="w-full py-10 border-4 border-dashed border-gray-100 rounded-[4rem] text-gray-400 hover:text-indigo-600 hover:border-indigo-300 hover:bg-indigo-50 transition-all font-black text-[15px] uppercase tracking-[0.5em] flex justify-center items-center gap-8 shadow-sm active:translate-y-1">
                  <span className="text-5xl">+</span> ADD {type.toUpperCase()} ROW
                </button>
              </div>
            </FormCard>
          );
        })}

        {/* Remarks Section */}
        <FormCard>
           <label className="block text-[15px] font-black text-gray-900 uppercase tracking-widest mb-6 ml-1 flex items-center gap-5">
             <div className="bg-indigo-100 p-3 rounded-2xl shadow-sm">
               <svg className="w-8 h-8 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z"/></svg>
             </div>
             Expense Remarks / Purpose
           </label>
           <textarea 
            rows={6}
            value={formData.remark}
            onChange={(e) => setFormData({ ...formData, remark: e.target.value })}
            placeholder="Describe the business purpose of these expenses in detail..."
            className="w-full bg-gray-50/50 border-4 border-transparent border-b-gray-100 py-10 px-10 focus:border-indigo-600 focus:bg-white outline-none transition-all resize-none text-base font-black rounded-t-[4rem] shadow-inner placeholder-gray-300"
           />
        </FormCard>

        {/* Submit Actions */}
        <div className="flex flex-col sm:flex-row justify-between items-center pb-24 gap-12 mt-12">
           <button 
            type="submit" 
            disabled={isSubmitting || grandTotal === 0}
            className={`w-full sm:w-auto px-24 py-6 rounded-full text-white font-black text-2xl shadow-2xl transition-all duration-300 flex items-center justify-center gap-6 ${isSubmitting || grandTotal === 0 ? 'bg-gray-200 cursor-not-allowed text-gray-400 shadow-none' : 'bg-indigo-600 hover:bg-indigo-700 hover:-translate-y-2 active:scale-95 shadow-indigo-300/80'}`}
           >
            {isSubmitting ? (
              <>
                <svg className="animate-spin h-8 w-8 text-white" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                SAVING...
              </>
            ) : (
              <>
                SUBMIT
                <svg className="w-8 h-8 opacity-40" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
              </>
            )}
           </button>
           <button 
             type="button" 
             onClick={() => confirm('Discard current draft?') && window.location.reload()} 
             className="text-gray-400 hover:text-red-600 font-black text-[14px] uppercase tracking-[0.6em] transition-all flex items-center gap-8 group px-12 py-7 hover:bg-red-50 rounded-full"
           >
             <svg className="w-10 h-10 transition-transform group-hover:rotate-180 duration-1000" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
             CLEAR
           </button>
        </div>
      </form>

      <footer className="text-center pb-16 opacity-80 border-t-8 border-gray-100 pt-16 px-12">
           <p className="text-[18px] text-gray-900 font-black uppercase tracking-[1em] mb-5">
             Ginza Industries Limited
           </p>
           <p className="text-[13px] text-gray-400 font-bold uppercase tracking-[0.4em]">
             Authorized Finance & Management Portal &copy; {new Date().getFullYear()}
           </p>
      </footer>
    </div>
  );
};

export default App;
